  'I need help with my account' => 'ကျွန်ုပ်၏အကောင့်အတွက် အကူအညီလိုပါသည်။',
  'icon-button mini-icon' => 'အိုင်ကွန်-ခလုတ်အသေး-အိုင်ကွန်',
  'If approved, payment is returned through the original method.' => 'အတည်ပြုပါက၊ ငွေပေးချေမှုကို မူရင်းနည်းလမ်းဖြင့် ပြန်ပေးပါသည်။',
  'If no paid transaction exists in the connected billing provider or platform records, there is no platform charge to refund. Refunds can only be reviewed against payment records, subscription IDs, invoices, or transaction references.' => 'ချိတ်ဆက်ထားသော ငွေပေးချေမှုဝန်ဆောင်မှုပေးသူ သို့မဟုတ် ပလပ်ဖောင်းမှတ်တမ်းများတွင် အခပေးငွေပေးချေမှု မရှိပါက၊ ပြန်အမ်းရန် ပလပ်ဖောင်းတွင် အခကြေးငွေ မရှိပါ။ ပြန်အမ်းငွေများကို စစ်မှန်သော ငွေပေးချေမှုမှတ်တမ်းများ၊ စာရင်းသွင်းမှု ID၊ ငွေတောင်းခံလွှာများ သို့မဟုတ် ငွေပေးငွေယူကိုးကားချက်များတို့နှင့်သာ စိစစ်နိုင်ပါသည်။',
