  'Payment help' => 'ငွေပေးချေမှုအကူအညီ',
  'Platform' => 'ပလပ်ဖောင်း',
  'Playback' => 'ပြန်ဖွင့်သည်။',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'ပြန်ဖွင့်သည့်တိုးတက်မှု၊ နောက်မှကြည့်ရှုသည့်အခြေအနေ၊ လိုက်ခ်များ၊ မှတ်ချက်များ၊ စာရင်းသွင်းမှုများ၊ အကြောင်းကြားချက်များနှင့် စီမံခန့်ခွဲသူဆိုင်ရာ ခွဲခြမ်းစိတ်ဖြာမှုများကို စစ်မှန်ကြောင်းအတည်ပြုထားသော ပလပ်ဖောင်းအင်္ဂါရပ်များနှင့် ချိတ်ဆက်သည့်အခါ ဒေတာဘေ့စ်တွင် သိမ်းဆည်းထားသည်။',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'ပြန်ဖွင့်ခြင်း၊ မှတ်ချက်များ၊ ကြိုက်နှစ်သက်မှုများ၊ နောက်မှကြည့်ရှုခြင်း၊ စာရင်းသွင်းမှုများ၊ အကြောင်းကြားချက်များ၊ မက်ဆေ့ချ်များ၊ အစီအစဉ်များနှင့် ဘာသာစကားဆက်တင်များကို ပင်မလမ်းညွှန်ချက်နှင့် အကောင့်မီနူးမှတဆင့် ရနိုင်ပါသည်။',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub သည် အကောင့်တစ်ခုမှ ဖန်တီးသူအကြောင်းအရာကို အပ်လုဒ်လုပ်ခြင်း၊ ကြည့်ရှုခြင်း၊ အချိန်ဇယားဆွဲခြင်း၊ စီမံခန့်ခွဲခြင်းနှင့် ထိန်းညှိခြင်းအတွက် ဗီဒီယိုပလပ်ဖောင်းတစ်ခုဖြစ်သည်။',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub သည် ဖန်တီးသူများ၊ ကြည့်ရှုသူများ၊ အသိုင်းအဝိုင်းများနှင့် ပလက်ဖောင်းအော်ပရေတာများအတွက် တည်ဆောက်ထားသည့် ဤအသုံးချမှုတွင် လုပ်ဆောင်နေသည့် ဗီဒီယိုပလက်ဖောင်းဖြစ်သည်။',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub သည် ထုတ်လုပ်သူချန်နယ်များ၊ ဗီဒီယို အပ်လုဒ်များ၊ စီစဉ်ထားသော ထုတ်ဝေမှု၊ စာရင်းသွင်းမှုများ၊ မှတ်ချက်များ၊ အစီအစဉ်များ၊ နောက်မှကြည့်ရှုရန်၊ တိုက်ရိုက်အကြောင်းအရာစာမျက်နှာများနှင့် ပလပ်ဖောင်းတစ်ခုမှ စီမံခန့်ခွဲရေးကိရိယာများကို ပံ့ပိုးပေးပါသည်။',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub သည် လော့ဂ်အင်ဆက်ရှင်များအတွက် မရှိမဖြစ်လိုအပ်သော ကွတ်ကီးများနှင့် ဘရောက်ဆာ သိုလှောင်မှုကို အသုံးပြုသည်၊ အပလီကေးရှင်းတွင် အလုပ်လုပ်ရန်အတွက် လိုအပ်သော API အထောက်အထားစိစစ်ခြင်း၊ CSRF/လုံခြုံရေးအမူအကျင့်၊ ဘာသာစကားရွေးချယ်မှု၊ အပြင်အဆင်ရွေးချယ်မှု၊',
  'playhub_language, theme' => 'playhub_language၊ အပြင်အဆင်',
