  'Profile, login, security, and settings help.' => 'ပရိုဖိုင်၊ အကောင့်ဝင်ခြင်း၊ လုံခြုံရေးနှင့် ဆက်တင်များက ကူညီပေးသည်။',
  'Profile, security, and preferences.' => 'ပရိုဖိုင်၊ လုံခြုံရေးနှင့် စိတ်ကြိုက်များ။',
  'Public API route' => 'အများသူငှာ API လမ်းကြောင်း',
