  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'အကောင့်၊ ပရိုဖိုင်၊ စကားဝှက်၊ အကြောင်းကြားချက်၊ ကိုယ်ရေးကိုယ်တာနှင့် ဖန်တီးရှင် နှစ်သက်ရာများအတွက် ဆက်တင်များကို ဝင်ရောက်ပြီး အသုံးပြုပါ။ ထုတ်လုပ်သူ အပ်လုဒ်တင်ခြင်းနှင့် အကြောင်းအရာပြဿနာများသည် ဗီဒီယိုခေါင်းစဉ်၊ ချန်နယ်၊ ဘရောက်ဆာနှင့် အပ်လုဒ်စာမျက်နှာတွင် ပြသထားသည့် လုပ်ဆောင်မှုဆိုင်ရာ အမှားအယွင်းများ ပါဝင်သင့်သည်။',
  'Sign in for account support' => 'အကောင့်ပံ့ပိုးမှုအတွက် အကောင့်ဝင်ပါ။',
