  'Submit a billing or refund message to admin support.' => 'ငွေပေးချေခြင်း သို့မဟုတ် ပြန်အမ်းငွေ မက်ဆေ့ဂျ်ကို စီမံခန့်ခွဲသူထံ ပေးပို့ပါ။',
  'Submit refund request' => 'ပြန်အမ်းငွေ တောင်းဆိုချက်ကို တင်သွင်းပါ။',
  'Submit request' => 'တောင်းဆိုချက်ကို တင်ပြပါ။',
  'Subscription cancellation' => 'စာရင်းသွင်းမှု ပယ်ဖျက်ခြင်း။',
  'Support dashboard' => 'ဒက်ရှ်ဘုတ်ကို ပံ့ပိုးပါ။',
  'System status' => 'စနစ်အခြေအနေ',
  'Table' => 'စားပွဲ',
  'Taxonomies' => 'အဘိဓာန်များ',
  'Technical issue' => 'နည်းပညာကိစ္စ',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'လက်ရှိ PlayHub API နှင့် ပေါင်းစည်းပြီး အလုပ်အသွားအလာကို အပ်လုဒ်လုပ်ရန်အတွက် နည်းပညာမှတ်စုများ။',
  'Tell us more about your question or request...' => 'သင့်မေးခွန်း သို့မဟုတ် တောင်းဆိုမှုအကြောင်း ကျွန်ုပ်တို့ကို ပိုမိုပြောပြပါ...',
  'Terms of Use' => 'အသုံးပြုမှုစည်းမျဉ်းများ',
  'The configured' => 'ပြင်ဆင်ထားသည်။',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'ဆော့ဖ်ဝဲရေးသားသူ စာမျက်နှာသည် တိုက်ရိုက် Laravel နောက်ကွယ်မှ ချိတ်ဆက်ထားသည်- လမ်းကြောင်းစာရင်း၊ ဒေတာဘေ့စ် အရေအတွက်၊ အပ်လုဒ်ကန့်သတ်ချက်များနှင့် ပလပ်ဖောင်း မက်တာဒေတာကို /api/developers မှ တင်ထားသည်။',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'ရွေးချယ်ထားသော ဘာသာစကား၊ အပြင်အဆင်၊ ဖွင့်ရန် တန်းစီခြင်း၊ ကြည့်ရှုသည့် တိုးတက်မှုနှင့် အင်တာဖေ့စ်အခြေအနေကဲ့သို့သော ဦးစားပေးမှုများကို သိမ်းဆည်းထားသောကြောင့် စာမျက်နှာလမ်းညွှန်ခြင်းနှင့် ပြန်လည်စတင်ခြင်းများတွင် အတွေ့အကြုံသည် တသမတ်တည်းရှိနေပါသည်။',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'လုပ်ဆောင်ခြင်းအလုပ်သည် တင်ဆက်မှုများကို ကုဒ်လုပ်သည်၊ လိုအပ်သည့်အခါ ပုံသေးများကို ဖန်တီးပေးသည်၊ စာတန်းများကို သိမ်းဆည်းကာ လုပ်ဆောင်ချက်ပြီးသွားသောအခါ အဆင်သင့်ဖြစ်နေသော ဗီဒီယိုများကို အမှတ်အသားပေးသည်။ အစီအစဉ်ဆွဲသူက ၎င်းတို့ကို မထုတ်ပြန်မချင်း အနာဂတ်တွင် စီစဉ်ထားသည့် ဗီဒီယိုများကို သီးသန့်ထားရှိမည်ဖြစ်သည်။',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'အပ်လုဒ်စနစ်သည် ဒေတာဘေ့စ်-ကျောထောက်နောက်ခံပြုထားပြီး၊ API မှ အမျိုးအစားများနှင့် ဘာသာစကားများကို ပံ့ပိုးပေးသည်၊ အပ်လုဒ်လုပ်ထားသော ဗီဒီယိုများကို လုပ်ဆောင်ရန်၊ ပုံသေးနှင့် စာတန်းများကို သိမ်းဆည်းကာ၊ အစီအစဉ်ဆွဲထားသော အကြောင်းအရာများကို ထုတ်လွှင့်ချိန်အထိ သီးသန့်ထားရှိမည်ဖြစ်သည်။',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'ဤစာမျက်နှာတွင် စက်ရှင်များ၊ လုံခြုံရေး၊ ဦးစားပေးများ၊ ပြန်ဖွင့်ခြင်းနှင့် စစ်မှန်ကြောင်းသက်သေပြထားသော အင်္ဂါရပ်များအတွက် ကွတ်ကီးများနှင့် ဘရောက်ဆာသိုလှောင်မှုကို မည်သို့အသုံးပြုကြောင်း ဤစာမျက်နှာတွင် ရှင်းပြထားသည်။',
  'Ticket source' => 'လက်မှတ်အရင်းအမြစ်',
  'Top content categories' => 'ထိပ်တန်းအကြောင်းအရာ အမျိုးအစားများ',
  'Topic' => 'အကြောင်းအရာ',
  'Transaction / invoice' => 'ငွေလွှဲ/ပြေစာ',
  'Transaction / invoice ID' => 'ငွေပေးငွေယူ / ငွေတောင်းခံလွှာ ID',
  'Unable to send message.' => 'မက်ဆေ့ခ်ျပို့၍မရပါ။',
  'Unable to submit refund request.' => 'ပြန်အမ်းငွေ တောင်းဆိုချက်ကို မတင်ပြနိုင်ပါ။',
  'Understanding admin support tickets' => 'အက်မင်ထောက်ခံမှုလက်မှတ်များကို နားလည်ခြင်း။',
  'Upload and processing help' => 'အပ်လုဒ်လုပ်ခြင်းနှင့် လုပ်ဆောင်ခြင်း အကူအညီ',
  'Upload chunks' => 'အပိုင်းများကို တင်ပါ။',
  'Upload issues' => 'တင်ခြင်းကိစ္စများ',
  'Upload languages' => 'ဘာသာစကားများ တင်ပါ။',
  'Upload limit' => 'အပ်လုဒ်ကန့်သတ်ချက်',
  'Upload options' => 'ရွေးစရာများ အပ်လုဒ်လုပ်ပါ။',
  'Upload or processing' => 'အပ်လုဒ်လုပ်ခြင်း သို့မဟုတ် လုပ်ဆောင်ခြင်း။',
  'Upload page' => 'စာမျက်နှာကို တင်ပါ။',
  'Upload pipeline' => 'ပိုက်လိုင်းတင်တယ်။',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'တိုက်ရိုက် PlayHub ဒေတာဖြင့် အပ်လုဒ်လုပ်ခြင်း၊ ကြည့်ရှုခြင်း၊ စာရင်းသွင်းခြင်း၊ ထိန်းညှိခြင်းနှင့် တည်ဆောက်ပါ။',
  'Uploaded videos' => 'အပ်လုဒ်လုပ်ထားသော ဗီဒီယိုများ',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'အပ်လုဒ်လုပ်ထားသော ဗီဒီယိုများကို ဖွင့်၍ရနိုင်သော ပုံစံများဖြင့် ကုဒ်လုပ်ထားသည်။ စီမံဆောင်ရွက်ချိန်သည် ဖိုင်အရွယ်အစား၊ ကြာချိန်၊ ဆာဗာဝန်နှင့် တန်းစီခြင်းအခြေအနေအပေါ် မူတည်သည်။ အပ်လုဒ်စာမျက်နှာနှင့် Creator Studio သည် ဗီဒီယိုမှတ်တမ်းမှ အမှန်တကယ် လုပ်ဆောင်နေသည့် အခြေအနေကို ပြသသည်။',
  'Uploads, scheduling, and processing are available.' => 'အပ်လုဒ်များ၊ အချိန်ဇယားဆွဲခြင်းနှင့် လုပ်ဆောင်ခြင်းတို့ကို ရရှိနိုင်ပါသည်။',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => '/api/videos၊ ချန်နယ် အဆုံးမှတ်များနှင့် ဖန်တီးသူ အလုပ်အသွားအလာများအတွက် စစ်မှန်ကြောင်း အတည်ပြုထားသော လမ်းကြောင်းများကို အသုံးပြုပါ။',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'အက်ဒ်မင်များသည် အကြောင်းအရာအတိအကျကို ကိုးကားမှုရရှိစေရန် ဗီဒီယိုနှင့် မှတ်ချက်များအတွက် ပါ၀င်သော အစီရင်ခံစာလုပ်ဆောင်ချက်များကို အသုံးပြုပါ။ စီမံခန့်ခွဲသူ ဒက်ရှ်ဘုတ်စာမျက်နှာများသည် သုံးစွဲသူများ၊ အကြောင်းအရာ၊ အစီရင်ခံစာများ၊ ငွေရှာခြင်း၊ ခွဲခြမ်းစိတ်ဖြာခြင်း၊ ပံ့ပိုးမှု၊ အခန်းကဏ္ဍများနှင့် စနစ်ဆက်တင်များအတွက် တိုက်ရိုက်ဒေတာဘေ့စ်ဒေတာကို အသုံးပြုပါသည်။',
  'Use Contact Us' => 'ကျွန်ုပ်တို့ကို ဆက်သွယ်ပါ။',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'ဖိုင်အပ်လုဒ်များအတွက် ပုံမှန် API တောင်းဆိုမှုများနှင့် FormData အတွက် JSON ကို အသုံးပြုပါ။ တရားဝင်မှုကို ရှောင်မလွှဲပါနှင့်- အမျိုးအစားများနှင့် ဘာသာစကားများသည် ဒေတာဘေ့စ် ID များ၊ မြင်နိုင်စွမ်းကို အများသူငှာ၊ စာရင်းမသွင်းထားသော သို့မဟုတ် သီးသန့်အဖြစ် ကန့်သတ်ထားပြီး စာတန်းများသည် SRT၊ VTT သို့မဟုတ် TXT ဖိုင်များကို လက်ခံပါသည်။',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'သင့်ပရိုဖိုင်၊ လုံခြုံရေး၊ စကားဝှက်၊ အချက်နှစ်ချက် ပေးပို့မှု၊ စက်ပစ္စည်းများ၊ ဦးစားပေးများနှင့် အကြောင်းကြားချက် ရွေးချယ်မှုများကို အပ်ဒိတ်လုပ်ရန် ဆက်တင်များကို အသုံးပြုပါ။ သင့်အကောင့်ကို သင်ဝင်ရောက်၍မရပါက၊ အကောင့်ဝင်ရောက်မှုကို အသုံးပြုပြီး အကောင့်အီးမေးလ်ကို ဆိုက်စီမံခန့်ခွဲသူထံ ပေးပို့ပါ။',
  'Use the contact form' => 'ဆက်သွယ်ရန်ပုံစံကို အသုံးပြုပါ။',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'ဗီဒီယိုများ၊ မှတ်ချက်များနှင့် ကွန်မြူနတီပို့စ်များတွင် အစီရင်ခံစာလုပ်ဆောင်မှုများကို စီမံခန့်ခွဲသူများသည် အကြောင်းအရာအတိအကျကို ကိုးကားမှုရရှိစေရန် အသုံးပြုပါ။',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'အကြောင်းအရာများသည် ပလက်ဖောင်းစည်းမျဉ်းများကို ချိုးဖောက်နိုင်သည့်အခါ ဗီဒီယိုများ၊ မှတ်ချက်များနှင့် ကွန်မြူနတီပို့စ်များတွင် အစီရင်ခံစာလုပ်ဆောင်မှုများကို အသုံးပြုပါ။ ဤအစီရင်ခံစာများသည် တကယ့်အကြောင်းအရာမှတ်တမ်းနှင့် ချိတ်ဆက်ထားပြီး စီမံခန့်ခွဲသူများသည် အကြောင်းအရာအတိအကျကို ပြန်လည်သုံးသပ်နိုင်သောကြောင့် ယေဘုယျမက်ဆေ့ခ်ျထက် ပိုကောင်းပါသည်။',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'အကောင့်အကူအညီ၊ အကြောင်းအရာအစီရင်ခံစာများ၊ နည်းပညာဆိုင်ရာပြဿနာများနှင့် စီမံခန့်ခွဲသူတောင်းဆိုမှုများအတွက် မှန်ကန်သော PlayHub ချန်နယ်ကို အသုံးပြုပါ။',
  'Video categories' => 'ဗီဒီယိုအမျိုးအစားများ',
  'Video for everyone. Built for creators and viewers.' => 'လူတိုင်းအတွက် ဗီဒီယို။ တကယ့် ပလက်ဖောင်းဒေတာမှ တည်ဆောက်ထားသည်။',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'ဗီဒီယို အပ်လုဒ်လုပ်ခြင်း၊ အချိန်ဇယားဆွဲခြင်း၊ ပုံသေးများနှင့် လုပ်ဆောင်ခြင်းဆိုင်ရာ ပြဿနာများ။',
  'Videos, thumbnails, captions, processing.' => 'ဗီဒီယိုများ၊ ပုံသေးများ၊ စာတန်းများ၊ လုပ်ဆောင်ခြင်း။',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'ကြည့်ရှုသူများသည် အမျိုးအစားများကို ရှာဖွေကြည့်ရှုနိုင်သည်၊ ဗီဒီယိုများကို ရှာဖွေခြင်း၊ အကြောင်းအရာများကို ကြည့်ရှုခြင်း၊ ချန်နယ်များသို့ စာရင်းသွင်းခြင်း၊ နောက်မှကြည့်ရှုရန် ဗီဒီယိုများကို သိမ်းဆည်းခြင်း၊ မှတ်ချက်ပေးခြင်း၊ အကြောင်းကြားချက်များကို လက်ခံရယူခြင်း၊ ဘာသာစကားနှင့် အသုံးပြုနိုင်မှုဆိုင်ရာ စိတ်ကြိုက်ရွေးချယ်မှုများကို စီမံခန့်ခွဲနိုင်ပါသည်။',
  'Viewing and community help' => 'ကြည့်ရှုခြင်းနှင့် ရပ်ရွာအကူအညီ',
  'Waiting for backend endpoint inventory.' => 'နောက်ခံအဆုံးမှတ်စာရင်းကို စောင့်နေသည်။',
  'We’re here to help.' => 'ကူညီရန် ကျွန်ုပ်တို့ ဤနေရာတွင် ရှိနေပါသည်။',
  'What is PlayHub?' => 'PlayHub ဆိုတာဘာလဲ။',
  'What PlayHub does' => 'PlayHub က ဘာလဲ။',
  'Where do contact messages go?' => 'ဆက်သွယ်ရန် မက်ဆေ့ဂျ်များ ဘယ်ရောက်သွားလဲ။',
  'Why is my video still processing?' => 'ကျွန်ုပ်၏ဗီဒီယိုကို အဘယ်ကြောင့် ဆက်လက်လုပ်ဆောင်နေသနည်း။',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'ဟုတ်ကဲ့။ အပ်လုဒ်စာမျက်နှာရှိ မူရင်းအချိန်ဇယားရက်စွဲနှင့် အချိန်အကွက်ကို အသုံးပြုပါ။ နောက်ခံလူသည် အချိန်ဇယားဆွဲပြီး_at ကို သိမ်းဆည်းသည်၊ ဗီဒီယိုကို လုပ်ဆောင်သည်၊ ရက်စွဲသည် အနာဂတ်တွင် ရှိနေစဉ်တွင် ၎င်းကို သီးသန့်ထားကာ၊ Laravel အစီအစဉ်ဆွဲသူသည် စီစဉ်ထားသည့်အချိန်ပြီးနောက် အလုပ်လုပ်သည့်အခါ ၎င်းကို ထုတ်ပေးသည်။',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'ဟုတ်ကဲ့။ Upload တွင် မူရင်းအချိန်ဇယားအကွက်ကို အသုံးပြုပါ။ နောက်ခံလူသည် scheduled_at ကို သိမ်းဆည်းထားပြီး အချိန်ဇယားအချိန်ပြည့်သွားသောအခါ လုပ်ဆောင်ပြီးနောက် ဗီဒီယိုကို ထုတ်ဝေသည်။',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'သင်သည် ဧည့်သည်အဖြစ် ကြည့်ရှုနေပါသည်။ အကောင့်အလိုက် ကိရိယာများကို အသုံးပြုရန် အကောင့်ဝင်ပါ။',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'သင့်အကောင့်အထောက်အထားများ၊ ပရိုဖိုင်လုပ်ဆောင်ချက်၊ အပ်လုဒ်လုပ်ထားသော အကြောင်းအရာ၊ မှတ်ချက်များ၊ မက်ဆေ့ချ်များနှင့် သင့်အကောင့်မှလုပ်ဆောင်ခဲ့သော ဖန်တီးရှင် သို့မဟုတ် စီမံခန့်ခွဲရေးလုပ်ဆောင်ချက်များအတွက် သင်သည် တာဝန်ရှိပါသည်။ ခိုင်မာသော စကားဝှက်များကို သုံး၍ အချက်နှစ်ချက် ပေးပို့ခြင်းနည်းလမ်းများကို လက်ရှိ ထားရှိပါ။',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'သင့်ဘရောက်ဆာဆက်တင်များတွင် ဘရောက်ဆာကွတ်ကီးများနှင့် စက်တွင်းသိုလှောင်မှုကို သင်ရှင်းလင်းနိုင်သည်။ မရှိမဖြစ်လိုအပ်သော သိုလှောင်ခန်းကို ရှင်းလင်းခြင်းသည် သင့်အား ထွက်သွားစေသည်၊ ဘာသာစကား/အပြင်အဆင် စိတ်ကြိုက်ရွေးချယ်မှုများကို ပြန်လည်သတ်မှတ်နိုင်သည်၊ စက်တွင်းဖွင့်ခြင်းအခြေအနေကို ဖယ်ရှားကာ သင့်အား ထပ်မံဝင်ရောက်ရန် လိုအပ်ပါသည်။',
  'You receive a response by email.' => 'သင်သည် အီးမေးလ်ဖြင့် တုံ့ပြန်မှုကို လက်ခံရရှိသည်။',
