  'Select an enabled service and paste a public video URL. PlayHub will fetch the details and play it from the original provider.' => 'ဖွင့်ထားသည့် ဝန်ဆောင်မှုကို ရွေးပြီး အများသူငှာ ဗီဒီယို URL ကို ကူးထည့်ပါ။ PlayHub သည် အသေးစိတ်အချက်အလက်များကို ရယူပြီး မူရင်းဝန်ဆောင်မှုပေးသူထံမှ ဖွင့်ပါမည်။',
